extern "C" int sprintf(char *, const char *, ...);

typedef float rational_t;
typedef float time_value_t;
typedef int device_id_t;
typedef int control_id_t;

const device_id_t JOYSTICK_DEVICE = 1;
const rational_t AXIS_MAX = 1.0f;

enum
{
  PSX_X = 184,
  PSX_CIRCLE,
  PSX_TRIANGLE,
  PSX_SQUARE,
  PSX_L1,
  PSX_L2,
  PSX_L3,
  PSX_R1,
  PSX_R2
};

enum
{
  ANIM_PRIMARY = 0,
  ANIM_LOOPING = 0x0004,
  ANIM_NONCOSMETIC = 0x0200,
  ANIM_TWEEN = 0x0800
};

#define BLEND_TIME 0.3f

class stringx
{
  char *chars;
  void *my_buf;

public:
  const char *c_str() const { return chars; }
};

class input_mgr
{
public:
  static input_mgr *inst();
  rational_t get_control_state(device_id_t, control_id_t) const;
};

class entity_anim_tree;

class entity
{
public:
  entity_anim_tree *play_anim(int, const stringx &, time_value_t,
                              unsigned short = 0, short = -1);
};

class generic_anim
{
public:
  virtual ~generic_anim() {}
  virtual void update(bool, bool, bool, float *) = 0;
  virtual void spawn() = 0;
  virtual void switch_anims() = 0;

protected:
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
};

class generic_anim_ice : public generic_anim
{
public:
  virtual ~generic_anim_ice() {}
  void update(bool, bool, bool, float *);
  void spawn();
  void switch_anims();

private:
  static const char* generic_anim_names[];
  int generic_anims[3];
  int generic_anim_state;
  entity *my_entity;

  typedef enum { IA_IDLE, IA_COLLIDE, IA_COLLIDEI, IA_SPAWN };
};

void generic_anim_ice::switch_anims ()
{
	if (!dummy)
		return;

	input_mgr* inputmgr = input_mgr::inst();

	if (inputmgr->get_control_state(JOYSTICK_DEVICE, PSX_L1) == AXIS_MAX)
	{
		if (!left_down)
		{
			left_down = true;
			cur_anim--;

			if (cur_anim <= 0)
			{
				cur_state--;

				if (cur_state < 0)
					cur_state = IA_COLLIDEI;

				cur_anim = generic_anims[cur_state];
			}

			char anim[256];
			sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
	    my_entity->play_anim (ANIM_PRIMARY, anim, BLEND_TIME, ANIM_LOOPING | ANIM_TWEEN | ANIM_NONCOSMETIC);
		}
	}
	else
	{
		left_down = false;
	}

	if (inputmgr->get_control_state(JOYSTICK_DEVICE, PSX_R1) == AXIS_MAX)
	{
		if (!right_down)
		{
			right_down = true;
			cur_anim++;

			if (cur_anim > generic_anims[cur_state])
			{
				cur_anim = 1;
				cur_state++;
				if (cur_state > IA_COLLIDEI)
					cur_state = 0;
			}

			char anim[256];
			sprintf (anim, "%s_%s_%d", my_base_name.c_str(), generic_anim_names[cur_state], cur_anim);
			my_entity->play_anim (ANIM_PRIMARY, anim, BLEND_TIME, ANIM_LOOPING | ANIM_TWEEN | ANIM_NONCOSMETIC);
		}
	}
	else
	{
		right_down = false;
	}
}
